package com.production.maintenance.model;
import jakarta.persistence.*; import java.time.LocalDate; import java.time.LocalDateTime;
@Entity @Table(name="maintenance_requests") public class MaintenanceRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long machineId; private String title; private String maintenanceType="PREVENTIVE"; private String priority="MEDIUM"; private String status="OPEN"; private String assignedTechnician; private LocalDate dueDate; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime completedAt; @Column(length=2000) private String workNotes; public MaintenanceRequest(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getMachineId(){return machineId;} public void setMachineId(Long v){machineId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMaintenanceType(){return maintenanceType;} public void setMaintenanceType(String v){maintenanceType=v;} public String getPriority(){return priority;} public void setPriority(String v){priority=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getAssignedTechnician(){return assignedTechnician;} public void setAssignedTechnician(String v){assignedTechnician=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getCompletedAt(){return completedAt;} public void setCompletedAt(LocalDateTime v){completedAt=v;} public String getWorkNotes(){return workNotes;} public void setWorkNotes(String v){workNotes=v;} }
